```javascript
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, mix, smoothstep, time, uniform, color } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Vector3, Quaternion } = ctx.THREE;

  // ─────────────────────────────────────────────────────────────
  // 1. ROOT & TIMELINES
  // ─────────────────────────────────────────────────────────────
  const root = new Group();
  const timelines = [];
  let activeIndex = 0;
  const navItems = ['HOME', 'FEATURES', 'COLLECTION', 'PRICING', 'JOURNAL'];
  const navRoutes = [
    'hub-home',
    'hub-features',
    'hub-collection',
    'hub-pricing',
    'hub-journal'
  ];

  // ─────────────────────────────────────────────────────────────
  // 2. CONTACT SHADOW PLANE
  // ─────────────────────────────────────────────────────────────
  const shadowGeom = new PlaneGeometry(3.6, 0.5);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
    depthWrite: false
  });
  const shadowPlane = new Mesh(shadowGeom, shadowMat);
  shadowPlane.position.z = -0.03;
  shadowPlane.position.y = -0.06;
  root.add(shadowPlane);

  // ─────────────────────────────────────────────────────────────
  // 3. MAIN RAIL (brushed metal with vertical albedo gradient)
  // ─────────────────────────────────────────────────────────────
  const railGeom = new PlaneGeometry(3.6, 0.5);

  // Shader nodes for vertical gradient (dark at top, lighter at bottom)
  const gradTop = color(0x1b1b23);
  const gradBot = color(0x101015);
  const gradFactor = uv().y; // 0 at bottom, 1 at top in default UV
  const albedoColor = mix(gradBot, gradTop, gradFactor);

  const railMat = new MeshStandardNodeMaterial({
    colorNode: albedoColor,
    roughnessNode: uniform(0.55),
    metalnessNode: uniform(0.5),
    clearcoatNode: uniform(0.2),
    emissiveNode: color(0x000000),
    transparent: false
  });

  // Anisotropy approximation: we'll rely on the PBR roughness
  // and the gradient to simulate the brushed metal effect
  const rail = new Mesh(railGeom, railMat);
  rail.position.z = 0.15;
  rail.userData.isRail = true;
  root.add(rail);

  // ─────────────────────────────────────────────────────────────
  // 4. NAV ENTRIES (text + interaction cells)
  // ─────────────────────────────────────────────────────────────
  const entries = [];
  const entryGroup = new Group();
  root.add(entryGroup);

  const cellWidth = 0.6;
  const cellHeight = 0.34;
  const spacing = 0.68;
  const startX = -2 * spacing;

  for (let i = 0; i < navItems.length; i++) {
    const item = navItems[i];
    const route = navRoutes[i];
    const isActive = i === 0;

    // Text mesh for the nav label
    const textContent = item;
    const fontSize = 13;
    const textColor = isActive ? '#e8ecf2' : '#a6adba';
    const textMesh = ctx.fontAtlas.createText(textContent, {
      fontSize,
      color: textColor,
      align: 'center',
      letterSpacingPx: 0.08 * fontSize
    });
    textMesh.position.set(startX + i * spacing, 0, 0.2);
    textMesh.userData.navIndex = i;
    textMesh.userData.route = route;
    textMesh.userData.isNavText = true;

    // Underline bar for active state
    let underlineBar = null;
    if (isActive) {
      const underlineGeom = new PlaneGeometry(0.28, 0.025);
      const underlineMat = new MeshBasicNodeMaterial({
        color: 0xff2a38,
        emissive: 0xff2a38,
        emissiveIntensity: 1.8,
        transparent: false,
        depthTest: true
      });
      underlineBar = new Mesh(underlineGeom, underlineMat);
      underlineBar.position.set(startX + i * spacing, -0.12, 0.21);
      underlineBar.userData.isUnderline = true;
      entryGroup.add(underlineBar);
    }

    entries.push({
      index: i,
      item,
      route,
      textMesh,
      underlineBar,
      centerX: startX + i * spacing,
      isActive
    });

    entryGroup.add(textMesh);
  }

  // ─────────────────────────────────────────────────────────────
  // 5. HOVER & PRESS INTERACTION CELLS
  // ─────────────────────────────────────────────────────────────
  const hitCells = [];
  for (let i = 0; i < navItems.length; i++) {
    const hitGeom = new PlaneGeometry(cellWidth, cellHeight);
    const hitMat = new MeshBasicNodeMaterial({
      transparent: true,
      opacity: 0,
      depthWrite: false
    });
    const hitMesh = new Mesh(hitGeom, hitMat);
    hitMesh.position.set(startX + i * spacing, 0, 0.25);
    hitMesh.userData.navIndex = i;
    hitMesh.userData.isHitCell = true;
    entryGroup.add(hitMesh);
    hitCells.push(hitMesh);
  }

  // ─────────────────────────────────────────────────────────────
  // 6. EVENT HANDLERS
  // ─────────────────────────────────────────────────────────────
  const handlers = {
    pointerOver: (evt) => {
      if (!evt.object || !evt.object.userData.isHitCell) return;
      const idx = evt.object.userData.navIndex;
      if (idx === activeIndex) return; // already active

      const entry = entries[idx];
      const newColor = color(0xe8ecf2);
      const oldColor = color(0xa6adba);

      const tl = gsap.timeline();
      timelines.push(tl);

      tl.to(entry.textMesh, {
        colorNode: newColor,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      }, 0);
    },

    pointerOut: (evt) => {
      if (!evt.object || !evt.object.userData.isHitCell) return;
      const idx = evt.object.userData.navIndex;
      if (idx === activeIndex) return;

      const entry = entries[idx];
      const inactiveColor = color(0xa6adba);

      const tl = gsap.timeline();
      timelines.push(tl);

      tl.to(entry.textMesh, {
        colorNode: inactiveColor,
        duration: 0.16,
        ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
      }, 0);
    },

    pointerDown: (evt) => {
      if (!evt.object || !evt.object.userData.isHitCell) return;
      const idx = evt.object.userData.navIndex;

      const hitCell = hitCells[idx];
      const tl = gsap.timeline();
      timelines.push(tl);

      tl.to(hitCell.position, {
        z: 0.22,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
      }, 0);

      tl.to(hitCell.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)'
      }, 0);
    },

    pointerUp: (evt) => {
      if (!evt.object || !evt.object.userData.isHitCell) return;
      const idx = evt.object.userData.navIndex;

      const hitCell = hitCells[idx];
      const tl = gsap.timeline();
      timelines.push(tl);

      tl.to(hitCell.position, {
        z: 0.25,
        duration: 0.2,
        ease: 'power2.out'
      }, 0);

      tl.to(hitCell.scale, {
        x: 1,
        y: 1,
        duration: 0.2,
        ease: 'power2.out'
      }, 0);
    },

    click: (evt) => {
      if (!evt.object || !evt.object.userData.isHitCell) return;
      const idx = evt.object.userData.navIndex;
      if (idx === activeIndex) return;

      const newEntry = entries[idx];
      const oldEntry = entries[activeIndex];

      // Update active state
      activeIndex = idx;

      // Animate underline bar to new position
      if (oldEntry.underlineBar) {
        entryGroup.remove(oldEntry.underlineBar);
      }

      const underlineGeom = new PlaneGeometry(0.28, 0.025);
      const underlineMat = new MeshBasicNodeMaterial({
        color: 0xff2a38,
        emissive: 0xff2a38,
        emissiveIntensity: 1.8,
        transparent: false,
        depthTest: true
      });
      const newUnderline = new Mesh(underlineGeom, underlineMat);
      newUnderline.position.set(oldEntry.centerX, -0.12, 0.21);
      newUnderline.userData.isUnderline = true;
      entryGroup.add(newUnderline);

      const tl = gsap.timeline();
      timelines.push(tl);

      // Transition underline X position with overshoot
      tl.to(newUnderline.position, {
        x: newEntry.centerX,
        duration: 0.26,
        ease: 'cubic-bezier(0.165,0.84,0.44,1)',
        overwrite: 'auto'
      }, 0);

      // Animate old text to inactive color
      tl.to(oldEntry.textMesh, {
        colorNode: color(0xa6adba),
        duration: 0.26
      }, 0);

      // Animate new text to active color
      tl.to(newEntry.textMesh, {
        colorNode: color(0xe8ecf2),
        duration: 0.26
      }, 0);

      // Update references
      newEntry.underlineBar = newUnderline;
      oldEntry.underlineBar = null;

      // Emit navigation event
      ctx.emit('navigate', { to: newEntry.route });
    }
  };

  // ─────────────────────────────────────────────────────────────
  // 7. MOUNT ANIMATION (rise-in)
  // ─────────────────────────────────────────────────────────────
  root.position.y = 0.4;

  const mountTl = gsap.timeline();
  timelines.push(mountTl);
  mountTl.to(root.position, {
    y: 0,
    duration: 0.7,
    ease: 'cubic-bezier(0.215,0.61,0.355,1)'
  }, 0);

  // ─────────────────────────────────────────────────────────────
  // 8. CLEANUP
  // ─────────────────────────────────────────────────────────────
  root.userData.cleanup = () => {
    timelines.forEach((tl) => {
      if (tl) tl.kill();
    });
    timelines.length = 0;

    railMat.dispose();
    shadowMat.dispose();
    railGeom.dispose();
    shadowGeom.dispose();

    entries.forEach((entry) => {
      if (entry.textMesh) {
        entry.textMesh.geometry?.dispose();
        entry.textMesh.material?.dispose();
      }
      if (entry.underlineBar) {
        entry.underlineBar.geometry?.dispose();
        entry.underlineBar.material?.dispose();
      }
    });

    hitCells.forEach((cell) => {
      cell.geometry?.dispose();
      cell.material?.dispose();
    });
  };

  root.userData.handlers = handlers;

  return root;
}
